#!/usr/bin/env node
/**
 * Exports the Verora contract ABIs from the forge build output as a typed TypeScript module.
 *
 * Usage: forge build && node script/export-abis.mjs <output.ts> [<output2.ts> ...]
 *
 * Consumers (API, SDK, app) commit the generated file so they always match the deployed contracts.
 */
import { readFileSync, writeFileSync, mkdirSync } from 'node:fs';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = resolve(dirname(fileURLToPath(import.meta.url)), '..');

const CONTRACTS = [
  ['agentRegistryAbi', 'AgentRegistry'],
  ['queryConsumerAbi', 'QueryConsumer'],
  ['stakingPoolAbi', 'StakingPool'],
  ['paymentRouterAbi', 'PaymentRouter'],
  ['reputationManagerAbi', 'ReputationManager'],
  ['treasuryAbi', 'Treasury'],
];

const outputs = process.argv.slice(2);
if (outputs.length === 0) {
  console.error('Usage: node script/export-abis.mjs <output.ts> [...]');
  process.exit(1);
}

const sections = CONTRACTS.map(([exportName, contract]) => {
  const artifact = JSON.parse(readFileSync(join(root, 'out', `${contract}.sol`, `${contract}.json`), 'utf8'));
  return `export const ${exportName} = ${JSON.stringify(artifact.abi, null, 2)} as const;`;
});

const source = [
  '// Generated by verora-contracts/script/export-abis.mjs from the forge build output. Do not edit.',
  '',
  sections.join('\n\n'),
  '',
].join('\n');

for (const output of outputs) {
  const target = resolve(process.cwd(), output);
  mkdirSync(dirname(target), { recursive: true });
  writeFileSync(target, source);
  console.log(`Wrote ${target}`);
}
